TLM.f("Sancti/01-15",{"officium":"S. Pauli Primi Eremitæ et Confessoris","rule":["vide C5;","Gloria"],"fallback":"Commune/C5","from":{"GradualeP":"Commune/C5","Tractus":"Commune/C5","Postcommunio":"Commune/C5"},"sections":{"Introitus":[{"k":"ref","la":"Ps 91:13-14"},{"k":"text","la":"Justus ut palma florébit: sicut cedrus Líbani multiplicábitur: plantátus in domo Dómini: in átriis domus Dei nostri."},{"k":"ref","la":"Ps 91:2"},{"k":"text","la":"Bonum est confitéri Dómino: et psállere nómini tuo, Altíssime."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Justus ut palma florébit: sicut cedrus Líbani multiplicábitur: plantátus in domo Dómini: in átriis domus Dei nostri."}],"Oratio":[{"k":"text","la":"Deus, qui nos beáti Pauli Confessóris tui ánnua solemnitáte lætíficas: concéde propítius; ut, cujus natalítia cólimus, étiam actiónes imitémur."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio Epístolæ beáti Pauli Apóstoli ad Philippénses"},{"k":"ref","la":"Philipp 3:7-12"},{"k":"text","la":"Fratres: Quæ mihi fuérunt lucra, hæc arbitrátus sum propter Christum defriménta. Verúmtamen exístimo ómnia detriméntum esse propter eminéntem sciéntiam Jesu Christi, Dómini mei: propter quem ómnia detriméntum feci et árbitror ut stércora, ut Christum lucrifáciam et invéniar in illo, non habens meam justítiam, quæ ex lege est, sed illam, quæ ex fide est Christi Jesu: quæ ex Deo est justítia in fide, ad cognoscéndum illum, et virtútem resurrectiónis ejus, et societátem passiónum illíus: configurátus morti ejus: si quo modo occúrram ad resurrectiónem, quæ est ex mórtuis: non quod jam accéperim aut jam perféctus sim: sequor autem, si quo modo comprehéndam, in quo et comprehénsus sum a Christo Jesu."}],"Graduale":[{"k":"ref","la":"Ps 91:13; 91:14"},{"k":"text","la":"Justus ut palma florébit: sicut cedrus Líbani multiplicábitur in domo Dómini."},{"k":"ref","la":"Ps 91:3"},{"k":"text","la":"Annuntiándum mane misericórdiam tuam, et veritátem tuam per noctem."},{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Osee 14:6"},{"k":"text","la":"Justus germinábit sicut lílium: et florébit in ætérnum ante Dóminum. Allelúja."}],"GradualeP":[{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Jas 1:12"},{"k":"text","la":"Beátus vir, qui suffert tentatiónem: quóniam, cum probátus fúerit, accípiet corónam vitæ. Allelúja."},{"k":"ref","la":"Eccli 45:9"},{"k":"text","la":"Amávit eum Dóminus et ornávit eum: stolam glóriæ índuit eum. Allelúja."}],"Tractus":[{"k":"ref","la":"Ps 91:13; 91:14"},{"k":"text","la":"Justus ut palma florébit: sicut cedrus Líbani multiplicábitur in domo Dómini."},{"k":"ref","la":"Ps 91:3"},{"k":"text","la":"Ad annuntiándum mane misericórdiam tuam, et veritátem tuam per noctem."},{"k":"sep"},{"k":"rubric","la":"Tractus"},{"k":"ref","la":"Ps 111:1-3"},{"k":"text","la":"Beátus vir, qui timet Dóminum: in mandátis ejus cupit nimis."},{"k":"text","la":"Potens in terra erit semen ejus: generátio rectórum benedicétur.","mark":"V"},{"k":"text","la":"Glória et divítiæ in domo ejus: et justítia ejus manet in sǽculum sǽculi.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Matthǽum"},{"k":"ref","la":"Matt 11:25-30"},{"k":"text","la":"In illo témpore: Respóndens Jesus, dixit: Confíteor tibi, Pater, Dómine coeli et terræ, quia abscondísti hæc a sapiéntibus et prudéntibus, et revelásti ea párvulis. Ita, Pater: quóniam sic fuit plácitum ante te. Omnia mihi trádita sunt a Patre meo. Et nemo novit Fílium nisi Pater: neque Patrem quis novit nisi Fílius, et cui volúerit Fílius reveláre. Veníte ad me, omnes, qui laborátis et oneráti estis, et ego refíciam vos. Tóllite jugum meum super vos, et díscite a me, quia mitis sum et húmilis corde: et inveniétis réquiem animábus vestris. Jugum enim meum suáve est et onus meum leve."}],"Offertorium":[{"k":"ref","la":"Ps 20:2-3"},{"k":"text","la":"In virtúte tua, Dómine, lætábitur justus, et super salutáre tuum exsultábit veheménter: desidérium ánimæ ejus tribuísti ei. (Allelúja.)"}],"Secreta":[{"k":"text","la":"Laudis tibi, Dómine, hóstias immolámus in tuórum commemoratióne Sanctórum: quibus nos et præséntibus éxui malis confídimus et futúris."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Ps 63:11"},{"k":"text","la":"Lætábitur justus in Dómino, et sperábit in eo: et laudabúntur omnes recti corde(, allelúja, allelúja)."}],"Postcommunio":[{"k":"text","la":"Refécti cibo potúque cœlésti, Deus noster, te súpplices exorámus: ut, in cujus hæc commemoratióne percépimus, ejus muniámur et précibus."},{"k":"macro","name":"Per Dominum"}]},"hr":{"6b4668e2db0b0991":{"t":"Ps 91, 13-14, Ps 91, 2\n(Ps 91, 13-14) Kao palma cvjeta i kao libanski cedar raste pravednik zasađen u Gospodnjem domu, u trijemovima hrama Boga našega. (Ps 91, 2) Dobro je slaviti Gospodina, i pjevati tvojemu imenu, Svevišnji.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Ps 91, 13-14) Kao palma cvjeta i kao libanski cedar raste pravednik zasađen u Gospodnjem domu, u trijemovima hrama Boga našega."},"168cbb6178ee479e":{"t":"<i>Pomolimo se</i>.\nBože koji nas razveseljuješ godišnjom svetkovinom blaženog Pavla priznavaoca svoga, daj milostivo da nasljedujemo djela onoga koga rođendan slavimo.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"9fc5b33868e1626a":{"t":"Fil 3, 7-12\nČitanje Poslanice bl. Pavla apostola Filipljanima. Braćo, sve ono što mi je nešto vrijedilo držao sam radi Krista štetnim. Još više sve držim štetnim prema neusporedivom dobru spoznaje moga Gospodina Isusa Krista. Radi njega sam se odrekao svega i sve držim kao blato samo zato da steknem Krista i budem u njemu i to ne svojom pravednošću po zakonu, nego po vjeri Isusa Krista, pravednošću koja je po vjeri od Boga, da spoznam njega i moć njegova uskrsnuća, da budem dionik njegovih muka i postanem mu sličan u smrti, da na kakav način postignem uskrsnuće od mrtvih. Ovo ne kažem, kao da sam to već postigao, ili da sam već savršen. Ja i nadalje nastojim, da bih što dobio kao što je i mene pridobio Isus Krist."},"1f6e8b22abef8588":{"t":"Ps 91, 13-14, Ps 91, 3\n(Ps 91, 13-14) Kao palma cvjeta i kao libanski cedar raste pravednik u domu Gospodnjem. (Ps 91, 3) Jutrom naviješta milosrđe tvoje i noću tvoju vjernost.\n\nHoš 14, 6\n<i>Aleluja</i>, <i>aleluja</i>.\nPravednik raste kao ljiljan i vječno cvate pred Gospodinom. <i>Aleluja</i>.","v":"ad → ∅"},"bb0bd8107f5e0717":{"t":"Mt 11, 25-30\nSlijedi sveto Evanđelje po Mateju. U ono vrijeme: Zahvaljujem ti, Oče, Gospodaru neba i zemlje jer si ovo sakrio mudrima i razumnima, a objavio malenima. Da, Oče, jer ti se svidjelo tako! Moj je Otac predao meni sve, i nitko ne pozna Sina nego Otac, niti tko pozna Oca nego Sin i komu Sin hoće da objavi. Dođite k meni svi koji ste umorni i opterećeni i ja ću vas okrijepiti. Uzmite na sebe moj jaram i učite se od mene jer sam ja krotka i ponizna srca i naći ćete pokoj svojim dušama. Jer je moj jaram sladak i moje breme lako."},"4e296f3326e0e479":{"t":"Ps 20, 2-3\nU jakosti tvojoj, Gospodine, raduje se pravednik i kliče radi tvoga spasenja, jer si mu ispunio želju srca njegova."},"18a58d3552d982fb":{"t":"Posvećujemo ti, Gospodine, žrtve hvale na spomen tvojih svetih i uzdamo se da ćeš nas po njima izbaviti od sadašnjih i od budućih zala.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"404159d2e4df1ef4":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi, Gospodine, sveti Oče, svemogući vječni Bože, po Kristu Gospodinu našemu. – Po njemu tvoje veličanstvo hvale anđeli, klanjaju se gospodstva i dršću vlasti. Nebesa i nebeske sile i blaženi serafini zajedničkim klicanjem slave. Daj, molimo, s njima i naše glase primi dok govorimo poniznim hvalospjevom:"},"39cef7df1eb57bf5":{"t":"Ps 63, 11\nRaduje se pravednik u Gospodinu i uzda se u njega i vesele se svi koji imaju dobro srce."},"77eef81bf0c58a4e":{"t":"<i>Pomolimo se</i>.\nOkrijepljeni nebeskim jelom i pićem ponizno te molimo, Bože naš, da budemo zaštićeni molitvama onoga na čiji smo to spomen primili.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."}}});
